#!/bin/bash
set -e

# 1. Смотрим, что именно сломано (для диагностики)
nginx -t || true

# 2. Записываем корректный конфиг для сайта на порту 8080
#    (в условии сказано отдавать /srv/www/index.html)
cat > /etc/nginx/sites-enabled/app <<'EOF'
server {
    listen 8080;
    server_name localhost;
    root /srv/www;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

# 3. Убеждаемся, что основной конфиг подключает sites-enabled
grep -q 'sites-enabled' /etc/nginx/nginx.conf || \
    sed -i '/http {/a \    include /etc/nginx/sites-enabled/*;' /etc/nginx/nginx.conf

# 4. Проверяем конфигурацию
nginx -t

# 5. Запускаем или перезагружаем nginx
if pgrep -x nginx > /dev/null; then
    nginx -s reload
else
    nginx
fi

# 6. Проверяем, что страница отдаётся
sleep 1
curl -s http://localhost:8080/ | head -n 5

#!/bin/bash
# Удаляем обычные файлы старше 7 дней рекурсивно; каталоги не трогаем.
find /var/log/app -type f -mmin +10080 -delete

#!/bin/bash
set -e

CONF=/etc/nginx/sites-enabled/app

# Сохраняем сломанный конфиг для разбора
[ -f "$CONF" ] && cp -a "$CONF" "$CONF.broken"

# Минимальный корректный сервер на 8080, отдающий /srv/www
cat > "$CONF" <<'EOF'
server {
    listen 8080;
    server_name localhost;
    root /srv/www;
    index index.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF

# Проверка синтаксиса; при ошибке выходим с сообщением
nginx -t

# systemd нет: запускаем или перезагружаем вручную
if pgrep -f 'nginx: master process' >/dev/null 2>&1; then
    nginx -s reload
else
    nginx
fi

# Быстрая самопроверка
curl -s --max-time 5 http://localhost:8080/ | cmp -s - /srv/www/index.html \
    && echo "OK: nginx отдаёт /srv/www/index.html" \
    || echo "ВНИМАНИЕ: ответ не совпадает с index.html, проверьте логи /var/log/nginx/error.log"

#!/bin/bash
# Топ-5 IP по числу запросов с кодом 500 из combined-лога
# $1 в combined — IP; статус — первое поле после закрывающей кавычки запроса
awk -F'"' '{
    split($3, a, " ")
    if (a[1] == "500") {
        split($1, b, " ")
        c[b[1]]++
    }
} END { for (ip in c) print c[ip], ip }' /var/log/nginx/access.log \
| sort -k1,1nr -k2,2 \
| head -n 5 \
| awk '{print $2}' > /tmp/top_ips.txt

#!/bin/bash
CONF="/etc/app/app.conf"
[ -f "$CONF" ] || { echo "файл $CONF не существует" >&2; exit 1; }

cp -p "$CONF" "$CONF.bak"

if grep -qE '^[[:space:]]*#?[[:space:]]*max_connections[[:space:]]*=' "$CONF"; then
    # Заменяем первую найденную строку (закомментированную или нет) на активную
    # и удаляем остальные дубликаты, чтобы осталась ровно одна активная строка
    awk '
        BEGIN { done = 0 }
        /^[[:space:]]*#?[[:space:]]*max_connections[[:space:]]*=/ {
            if (!done) { print "max_connections=200"; done = 1 }
            next
        }
        { print }
    ' "$CONF" > "$CONF.tmp" && mv "$CONF.tmp" "$CONF"
else
    # Параметра нет: добавляем в конец, сохраняя перевод строки в конце файла
    [ -s "$CONF" ] && [ -n "$(tail -c1 "$CONF")" ] && echo >> "$CONF"
    echo "max_connections=200" >> "$CONF"
fi

grep -nE '^[[:space:]]*max_connections[[:space:]]*=' "$CONF"
